<?php declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$u=requireLogin();if($u['role']==='member'){flash('success','You are already an approved member.');redirect('member/profile.php');}$existing=db()->prepare("SELECT * FROM membership_applications WHERE user_id=? AND status='pending' ORDER BY id DESC LIMIT 1");$existing->execute([$u['id']]);$pending=$existing->fetch();$error='';if(post()&&!$pending){verifyCsrf();$mot=clean('motivation',5000);if(mb_strlen($mot)<30)$error='Please provide at least 30 characters explaining why you want to join.';else{db()->prepare('INSERT INTO membership_applications(user_id,motivation) VALUES(?,?)')->execute([$u['id'],$mot]);flash('success','Membership application submitted for admin review.');redirect('member/profile.php');}}$pageTitle='Membership';require __DIR__.'/includes/header.php';?><div class="form-shell"><p class="eyebrow">Membership</p><h1>Become an ATACJL member</h1><?php if($pending):?><p>Your application is currently <b>pending review</b>.</p><?php else:?><p>Members can comment, maintain a member profile and record event participation for verification.</p><?php if($error):?><div class="flash error" style="position:static"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="field"><label>Why would you like to become a member?</label><textarea name="motivation" required></textarea></div><button class="btn coral">Submit application</button></form><?php endif;?></div><?php require __DIR__.'/includes/footer.php';
